1	import {
2	  $,
3	  Slot,
4	  component$,
5	  useStore,
6	  type PropFunction,
7	} from "@qwik.dev/core";
8	import { steerBackgroundResearch } from "../../utils/background-research";
9	import { ChatComposer } from "../ui/chat-composer";
10	import type { ActivityCounts, PanelId } from "../../utils/panel-activity";
11	
12	export interface EditorialBoardTab {
13	  id: PanelId;
14	  numeral: string;
15	  label: string;
16	  kicker: string;
17	  accent: string;
18	}
19	
20	interface EditorialBoardOverlayProps {
21	  open: boolean;
22	  activeContext: PanelId;
23	  activity: ActivityCounts;
24	  tabs: EditorialBoardTab[];
25	  onContext$: PropFunction<(panel: PanelId) => void>;
26	  onClose$: PropFunction<() => void>;
27	}
28	
29	interface OverlayStore {
30	  steeringCollapsed: boolean;
31	  steeringDraft: string;
32	  steeringBusy: boolean;
33	  steeringNotice: string | null;
34	  steeringError: string | null;
35	}
36	
37	/**
38	 * The Editorial Board as furniture on the manuscript rather than another
39	 * application rail. Its children remain mounted while closed so searches,
40	 * streams, replies, and error recovery continue without losing state.
41	 */
42	export const EditorialBoardOverlay = component$<EditorialBoardOverlayProps>(
43	  (props) => {
44	    const store = useStore<OverlayStore>({
45	      steeringCollapsed: false,
46	      steeringDraft: "",
47	      steeringBusy: false,
48	      steeringNotice: null,
49	      steeringError: null,
50	    });
51	
52	    const submitSteering = $(async () => {
53	      const direction = store.steeringDraft.trim();
54	      if (!direction || store.steeringBusy) return;
55	      store.steeringBusy = true;
56	      store.steeringError = null;
57	      store.steeringNotice = null;
58	      const result = await steerBackgroundResearch(direction);
59	      store.steeringBusy = false;
60	      if (!result.ok) {
61	        store.steeringError =
62	          result.message ?? "The Apparatus could not start.";
63	        return;
64	      }
65	      store.steeringNotice = "Direction added to the next research pass.";
66	      store.steeringDraft = "";
67	    });
68	
69	    const activeTab =
70	      props.tabs.find((tab) => tab.id === props.activeContext) ?? props.tabs[0];
71	
72	    return (
73	      <aside
74	        class={[
75	          "editorial-overlay",
76	          {
77	            "editorial-overlay--apparatus": props.activeContext === "citations",
78	            "editorial-overlay--closed": !props.open,
79	          },
80	        ]}
81	        aria-label="The Editorial Board"
82	        aria-hidden={!props.open}
83	        onKeyDown$={(event, el) => {
84	          if (event.key !== "Escape" || event.defaultPrevented) return;
85	          const target = event.target as Element | null;
86	          // Only act while focus is inside the board, and leave open menus,
87	          // dialogs, and pickers to handle their own Escape.
88	          if (!target || !el.contains(target)) return;
89	          if (
90	            target.closest(
91	              '[role="menu"], [role="dialog"], [role="alertdialog"], [role="listbox"], [role="combobox"], dialog[open], select, [aria-expanded="true"][aria-haspopup]',
92	            )
93	          ) {
94	            return;
95	          }
96	          props.onClose$();
97	          document
98	            .querySelector<HTMLElement>(
99	              '[aria-label="Toggle the editorial board panel"]',
100	            )
101	            ?.focus();
102	        }}
103	      >
104	        <div class="editorial-overlay__topline">
105	          <p class="dept-label">The Editorial Board</p>
106	          <button
107	            type="button"
108	            class="editorial-overlay__close focus-ring"
109	            onClick$={props.onClose$}
110	            aria-label="Close the Editorial Board"
111	          >
112	            ×
113	          </button>
114	        </div>
115	
116	        <section
117	          class="editorial-overlay-card editorial-board-card"
118	          style={{ "--board-accent": activeTab.accent }}
119	        >
120	          <header class="editorial-board-card__head">
121	            <nav class="editorial-board-contexts" aria-label="Board context">
122	              {props.tabs.map((tab) => {
123	                const active = tab.id === props.activeContext;
124	                const unread = props.activity[tab.id] ?? 0;
125	                return (
126	                  <button
127	                    key={tab.id}
128	                    type="button"
129	                    class={[
130	                      "editorial-board-context focus-ring",
131	                      { "editorial-board-context--active": active },
132	                    ]}
133	                    style={{ "--context-accent": tab.accent }}
134	                    onClick$={() => props.onContext$(tab.id)}
135	                    aria-pressed={active}
136	                    aria-label={
137	                      unread > 0 ? `${tab.label} — ${unread} new` : tab.label
138	                    }
139	                  >
140	                    <span aria-hidden="true">{tab.numeral}</span>
141	                    <strong>{tab.label}</strong>
142	                    {unread > 0 && !active && (
143	                      <small aria-hidden="true">
144	                        {unread > 9 ? "9+" : unread}
145	                      </small>
146	                    )}
147	                  </button>
148	                );
149	              })}
150	            </nav>
151	          </header>
152	          {props.activeContext === "citations" && (
153	            <section class="editorial-steering-card">
154	              <header class="editorial-overlay-card__head">
155	                <p class="dept-label">Steer search</p>
156	                <button
157	                  type="button"
158	                  class="apparatus-disclosure-toggle focus-ring"
159	                  onClick$={() => {
160	                    store.steeringCollapsed = !store.steeringCollapsed;
161	                  }}
162	                  aria-expanded={!store.steeringCollapsed}
163	                  aria-label={
164	                    store.steeringCollapsed
165	                      ? "Expand research steering"
166	                      : "Collapse research steering"
167	                  }
168	                >
169	                  {store.steeringCollapsed ? "▸" : "▾"}
170	                </button>
171	              </header>
172	              {!store.steeringCollapsed && (
173	                <div class="editorial-steering-card__body">
174	                  {/* The same composer the rest of the room writes into: the
175	                      Steer key sits under the box instead of beside it, and a
176	                      direction can be spoken as readily as typed. */}
177	                  <ChatComposer
178	                    value={store.steeringDraft}
179	                    onValueChange$={$((value: string) => {
180	                      store.steeringDraft = value;
181	                      store.steeringError = null;
182	                      store.steeringNotice = null;
183	                    })}
184	                    onSend$={submitSteering}
185	                    busy={store.steeringBusy}
186	                    label="Research direction"
187	                    sendLabel="Steer"
188	                    placeholder="Prefer primary sources, trace the original quotation…"
189	                  />
190	                  {(store.steeringError || store.steeringNotice) && (
191	                    <p
192	                      class={
193	                        store.steeringError
194	                          ? "editorial-steering-card__error"
195	                          : "editorial-steering-card__notice"
196	                      }
197	                      role="status"
198	                    >
199	                      {store.steeringError ?? store.steeringNotice}
200	                    </p>
201	                  )}
202	                </div>
203	              )}
204	            </section>
205	          )}
206	          <div class="board-panel editorial-board-card__body">
207	            <Slot />
208	          </div>
209	        </section>
210	      </aside>
211	    );
212	  },
213	);
