1	import { component$, Slot, useStyles$ } from "@qwik.dev/core";
2	import styles from "./instrument-motion.css?inline";
3	
4	export type InstrumentMotionState = "rest" | "open" | "compare" | "arrive";
5	export type InstrumentMotionPartKind = "source" | "alternative" | "result";
6	
7	export interface InstrumentMotionProps {
8	  /** Use rest for restored content. Change state only for an actual interaction. */
9	  state?: InstrumentMotionState;
10	  /** Pass true while writing, in Zen, or when the host is outside the viewport. */
11	  quiet?: boolean;
12	  class?: string;
13	}
14	
15	/**
16	 * Finite feedback only: no timers, document listeners, or perpetual loader.
17	 * This wrapper never manages visibility or delays interaction with its children.
18	 */
19	export const InstrumentMotion = component$<InstrumentMotionProps>((props) => {
20	  useStyles$(styles);
21	  return (
22	    <div
23	      class={["instrument-motion", props.class]}
24	      data-instrument-motion={props.state ?? "rest"}
25	      data-instrument-quiet={props.quiet ? "true" : undefined}
26	    >
27	      <Slot />
28	    </div>
29	  );
30	});
31	
32	/** Mark the real comparison/result content, not a decorative stand-in. */
33	export const InstrumentMotionPart = component$<{
34	  part: InstrumentMotionPartKind;
35	  class?: string;
36	}>((props) => (
37	  <div class={props.class} data-instrument-part={props.part}>
38	    <Slot />
39	  </div>
40	));
41

1	.instrument-motion {
2	  --instrument-ease: cubic-bezier(0.22, 1, 0.36, 1);
3	}
4	
5	/* Content starts fully visible. Animation never gates a control or a result. */
6	@media (prefers-reduced-motion: no-preference) {
7	  .instrument-motion[data-instrument-motion="open"] .instrument-art__image {
8	    animation: instrument-open 220ms var(--instrument-ease);
9	  }
10	
11	  .instrument-motion[data-instrument-motion="compare"]
12	    [data-instrument-part="alternative"] {
13	    animation: instrument-compare 200ms var(--instrument-ease);
14	  }
15	
16	  .instrument-motion[data-instrument-motion="arrive"]
17	    [data-instrument-part="result"] {
18	    animation: instrument-result 240ms var(--instrument-ease);
19	  }
20	
21	  .instrument-motion[data-instrument-motion="arrive"] .instrument-art__rule {
22	    animation: instrument-rule 260ms var(--instrument-ease);
23	  }
24	}
25	
26	@keyframes instrument-open {
27	  from {
28	    opacity: 0.6;
29	    transform: translateY(4px);
30	  }
31	  to {
32	    opacity: 1;
33	    transform: none;
34	  }
35	}
36	
37	@keyframes instrument-compare {
38	  from {
39	    opacity: 0.6;
40	    transform: translateX(6px);
41	  }
42	  to {
43	    opacity: 1;
44	    transform: none;
45	  }
46	}
47	
48	@keyframes instrument-result {
49	  from {
50	    opacity: 0.5;
51	    transform: translateY(4px);
52	  }
53	  to {
54	    opacity: 1;
55	    transform: none;
56	  }
57	}
58	
59	@keyframes instrument-rule {
60	  from {
61	    opacity: 0.5;
62	    transform: scaleX(0.3);
63	  }
64	  to {
65	    opacity: 1;
66	    transform: none;
67	  }
68	}
69	
70	/* The host passes quiet for its exact typing/visibility state. Existing ambient
71	 * flow and Zen containers are supported as an additional, CSS-only safeguard. */
72	.instrument-motion[data-instrument-quiet="true"],
73	.instrument-motion[data-instrument-quiet="true"] *,
74	[data-flow="flow"] .instrument-motion,
75	[data-flow="flow"] .instrument-motion *,
76	[data-flow="settling"] .instrument-motion,
77	[data-flow="settling"] .instrument-motion *,
78	[data-zen="true"] .instrument-motion,
79	[data-zen="true"] .instrument-motion *,
80	.zen-mode .instrument-motion,
81	.zen-mode .instrument-motion * {
82	  animation: none !important;
83	  transition: none !important;
84	}
85	
86	@media (prefers-reduced-motion: reduce) {
87	  .instrument-motion,
88	  .instrument-motion * {
89	    animation: none !important;
90	    transition: none !important;
91	  }
92	}
