1	import { component$ } from "@qwik.dev/core";
2	import { StampPress } from "../ui/stamp-press";
3	import {
4	  rubricGradeStampAsset,
5	  rubricGradeTier,
6	} from "../../utils/rubric-feedback";
7	
8	interface GradeStampProps {
9	  grade: string;
10	  score: number;
11	  color: string;
12	  size?: "compact" | "report";
13	  animated?: boolean;
14	  /** Stable result identity: only a new verdict should receive a fresh press. */
15	  impressionKey?: string | number;
16	}
17	
18	/** A complete grade-specific impression, recolored by the active theme. */
19	export const GradeStamp = component$<GradeStampProps>((props) => {
20	  const tier = rubricGradeTier(props.grade);
21	  const asset = rubricGradeStampAsset(props.grade);
22	  const highest = props.grade.trim().toUpperCase() === "A+";
23	  return (
24	    <div
25	      class={[
26	        "rubric-grade-stamp",
27	        `rubric-grade-stamp--${props.size ?? "compact"}`,
28	        `rubric-grade-stamp--${tier}`,
29	        { "rubric-grade-stamp--highest": highest },
30	        { "rubric-grade-stamp--animated": props.animated },
31	      ]}
32	      style={{
33	        color: props.color,
34	        "--rubric-stamp-image": `url("${asset}")`,
35	      }}
36	      role="img"
37	      aria-label={`Overall grade ${props.grade}, ${props.score} of 100`}
38	    >
39	      <StampPress
40	        key={props.impressionKey ?? `${props.grade}:${props.score}`}
41	        animated={props.animated}
42	      >
43	        <span class="rubric-grade-stamp__mark" />
44	      </StampPress>
45	    </div>
46	  );
47	});
